def Grill (C : Family G) (F : Order) := ∀ d m : ℕ, ∃ k : ℕ, m≤k ∧ ∀ n : ℕ, ∀ v : Fin n → C.book.Token,
    (∀ i,(v i).fst ≤ d) → Grid.plain (C := C) v → ∀ x : Fin n→ Lattice.Cover, Order.grid C k x ∈ generic n →
    ∃ P : Grid.Covering (C:=C) k v x, Grid.Covering.Works k v x P F

theorem motor (m : ℕ) (V : Voice F H p (m+1)) {η C : ℝ}
    (hq : Heard B H N p A (m+1) V) (hw : roomCost H.levels W)
    (hb : Bank W H.levels) (T : Heading F)
    (D : GaugeDoor (H.rep N p (m+1)) (H.rep N p m))(Xk : Set Wing){t : ℝ}
    (R₀:Tool F H N p m)(hT₀:Tool.Cap R₀ B A W D T C η t Xk) (hr : Chorus H N p (m+1) V)
    {U:Desk G (H.S.side (m+1) p)}
    (hu:Well (H.rep N p (m+1)) U (Real.sqrt (H.levels.clock.forcedAllowance (m+1)))):
    let R:= measure hq R₀.up hu
    ∃ Q : Voice F H p m, (∀ v,Q.plays v = Gram.point R₀ R (V.index v)) ∧ (Heard B H N p A m Q ∧ Responds B H N p W m V Q ∧ Chorus H N p m Q∧ Carol B H N p m D V Q t) := by

def localTurn (p : Parts S) (T : SpinRows S) (K : Ortho.Skew) {n : ℕ} (q : Fin n → S.Tag) (x : Points n) :=
    ∑ i, (disc (update q i (turns T K (q i))) x + ∑ b : Axis, ((M4.move K.val (x i) b) •
      disc (update q i (⟨_,p _ b (q i).2⟩:S.Tag)) x))

def angular (q : Fin n → S.Tag) (K : Ortho.Skew) (x : Points n) :=
    ∑ i, (disc (update q i (turns T K (q i))) x +
         ∑ b : Axis, M4.move K.val (x i) b • disc (update q i (rise W b (q i))) x)

def Miles : Prop := ∀ {G : Gauge} {C : Family G} {F : Order} {S : Table C.book} (V : DiffPlan S) (W : MaxwellData C) (I : IR (C:=C) S)
    (_ : UV C F S V W I), V.Inclusions S → V.Derivatives S →
    LineSum I.p ∧ (∀ K a n (q : Fin n → S.Tag) (x : Points n), x∈conf _ → onLine a x → localTurn I.p I.Y K q x=0)

def localTurn (p : Parts S) (T : SpinRows S) (K : Ortho.Skew) {n : ℕ} (q : Fin n → S.Tag) (x : Points n) :=
    ∑ i, (disc (update q i (turns T K (q i))) x + ∑ b : Axis, ((M4.move K.val (x i) b) •
      disc (update q i (⟨_,p _ b (q i).2⟩:S.Tag)) x))

theorem exists_stress (h : G.Simple) (H : S.Hierarchy) (hw : W.Orientation H.spin) {A : (Bel L).RealSpin}
    (U4 : Spin.change S 4) (U5 : Spin.change S 5) (h4 : Spin.realH H.spin A U4) (h5 : Spin.realH H.spin A U5) :
    ∃ w : Coeff, ‖w‖ = 1 ∧ nabla W (material S w) = 0 ∧ Centers (material S w) := by

def A04 : Prop := ∀ {G : Gauge} {C : Family G} {S : Table C.book} (H : S.Hierarchy) (V : DiffPlan S),
    V.Inclusions S → V.Derivatives S → ∀ (R : MaxwellData C) (J : S.Stress) (d : ℕ),
    Watches J R.T H.spin R.hT.spin V (fun X => ConLap X V.deriv d R.T.W.deriv X.r)

def currentDiv (V : DiffPlan T) (H : T.RealSpin) (ho : V.Orientation H) : ↑(KernelSpace H) →ₗ[ℝ] ↑(Vectors H) :=
    (((rayDiv V).restrictScalars ℝ).comp (KernelSpace H).subtype).codRestrict (Vectors H)
      (fun v => vector_div H ho (kernel_mem.mp v.property).1)

def Miles : Prop := ∀ {G : Gauge} {C : Family G} {F : Order} {S : Table C.book} (V : DiffPlan S) (W : MaxwellData C) (I : IR (C:=C) S)
    (_ : UV C F S V W I), V.Inclusions S → V.Derivatives S →
    LineSum I.p ∧ (∀ K a n (q : Fin n → S.Tag) (x : Points n), x∈conf _ → onLine a x → localTurn I.p I.Y K q x=0)

