def B13 : Prop := ∀ {G : Gauge} {C : Family G} {S : Table C.book} (V : Chamber S timeAxis) (A : Spread V)
    (P : Spread.Resolution A) (X : Algebra S) (H : S.Hierarchy), Locals X H.spin → Steady V → A.Laws X.derivatives → Theme V A → P.Out →
    ∀ p, Phase.Scripts X V A P p → ∀ i (Z : Chamber (p i) timeAxis), ∃ B : Spread Z,B.AllCopy

def flash (N p t j : ℕ) (q : Config G (C.side N p)) :=
  let D : Cover := fun _ => t*j
  tiny h v x N p D q - tiny h (C:=C) (C.book.move (Signed.mirror timeAxis) ∘ v) ((Signed.mirror timeAxis).act ∘ x) N p D q

def action (Q : Wightman S) (K : Killing) (R : S.Rotation) (B : S.Tag) (m : Test4) :=
    Q.operators.field (S.pin B.1 (rankAction R B.1 K.V B.2)) m+
      ∑ i : Axis, Q.operators.field (S.pin B.1 B.2) (partialProbe i (touch K i m))

def receives (R : P.Resolution) (T : Table L) (i : R.X) :=
    ∀ (w : L.Word), distinct w → ∀ (s : E4) (d : ℝ≥0) (h : Slab timeAxis d (carry w s)),
      T.expect w = R.character i (P.slot _ _ h)

def polarization (p : Space3) (j k : SpaceAxis) : ℂ :=
    ifk j k - (((p j * p k / ‖p‖^2:ℝ)):ℂ)
  where ifk (j k : SpaceAxis) : ℂ := if j=k then 1 else 0

def rho (h : G.Simple) : RawOne G →ₗ[ℝ] ℝ :=
  ((-4:ℝ) • (LinearMap.proj (0:Fin 3)+(4:ℝ) • LinearMap.proj (1:Fin 3))) ∘ₗ
       (LinearEquiv.ofBijective bareVector (bareCoordinates h)).symm.toLinearMap

def checkReal (P:Prescription Q) {X:Rotation S}{ρ:S.RealSpin}(hX:X.Laws Q ρ)
    (hS:S.Hierarchy)(m:ℕ)(x:I→E4)(o:E4): MultilinearMap ℂ (fun i=>S.Field (d i)) (S.Field m) :=
        (2:ℂ)⁻¹ • (readMap P X hX hS m x o + barRow (P:=P) m hX hS x o)

def liftOne (m q:ℕ): S.Field q→ₗ[ℂ] S.Field m :=
    let f:= (checkReal R.port R.law R.continuum m (sole 0) 0 (d:=fun _:Unit=>q))
    f.toLinearMap 0 () -- 0 overwritten at ()

